vars.selected_academic_year_label = selected.academic_year_label || vars.selected_academic_year_label || "";
vars.selected_application_fee_amount_minor = Number(selected.application_fee_amount_minor || vars.selected_application_fee_amount_minor || 0);
vars.application_fee_display = selected.application_fee_display || vars.application_fee_display || "";
vars.applicant_name = selected.student_name || selected.applicant_name || vars.applicant_name || "";
vars.guardian_name = selected.guardian_name || vars.guardian_name || "";
vars.contact_mobile = selected.contact_mobile || vars.contact_mobile || "";
vars.contact_email = selected.contact_email || vars.contact_email || "";

vars.lookup_application_state = "selected";
return "success";

const status = String(vars.selected_application_status || "").toLowerCase();
const paymentStatus = String(vars.selected_payment_status || "").toLowerCase();
const documentStatus = String(vars.selected_document_status || "").toLowerCase();
let route = "profile";
if (
  status === "submitted" ||
  status === "shortlisted" ||
  status === "offer_issued" ||
  status === "admitted"
) {
  route = "status";
} else if (paymentStatus === "pending" || status === "payment_pending") {
  route = "payment";
} else if (
  documentStatus === "documents_pending" ||
  documentStatus === "missing" ||
  documentStatus === "needs_reupload" ||
  documentStatus === "manual_review"
) {
  route = "documents";
}
vars.resume_route = route;
return "success";

